/* Toast Notification */
.htmx-toast {
    position: fixed;
    top: 20px;
    left: 50%;
    transform: translateX(-50%) translateY(-20px);
    background: #0f172a;
    color: white;
    padding: 10px 20px;
    border-radius: 99px;
    font-family: 'Outfit', sans-serif;
    font-size: 13px;
    font-weight: 600;
    box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
    z-index: 2147483647;
    pointer-events: none;
    opacity: 0;
    transition: all 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
    display: flex;
    align-items: center;
    gap: 8px;
    border: 1px solid rgba(255,255,255,0.1);
}

.htmx-toast.visible {
    opacity: 1;
    transform: translateX(-50%) translateY(0);
}

.htmx-toast-icon {
    width: 16px;
    height: 16px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 10px;
}

.htmx-toast.success .htmx-toast-icon {
    background: #22c55e;
    color: white;
}

.htmx-toast.info .htmx-toast-icon {
    background: #94a3b8;
    color: white;
}
